import{_ as a,c as e,o as r,ak as o}from"./chunks/framework.14-H7uoj.js";const l="/img/png/408_CN/05.png",c=JSON.parse('{"title":"计算机网络的分类","titleTemplate":"408计算机网络","description":"综述","frontmatter":{"title":"计算机网络的分类","titleTemplate":"408计算机网络","description":"综述","layout":"doc","navbar":true,"sidebar":true,"aside":true,"outline":"deep","lastUpdated":true,"prev":false,"next":false},"headers":[],"relativePath":"post/kaoyan/408/408_CN/01/408_CN_5.md","filePath":"post/kaoyan/408/408_CN/01/408_CN_5.md","lastUpdated":1756187359000}'),p={name:"post/kaoyan/408/408_CN/01/408_CN_5.md"};function i(n,t,s,d,_,g){return r(),e("div",null,t[0]||(t[0]=[o('<h1 id="计算机网络的分类" tabindex="-1">计算机网络的分类 <a class="header-anchor" href="#计算机网络的分类" aria-label="Permalink to &quot;计算机网络的分类&quot;">​</a></h1><h2 id="按分布范围分类" tabindex="-1">按分布范围分类 <a class="header-anchor" href="#按分布范围分类" aria-label="Permalink to &quot;按分布范围分类&quot;">​</a></h2><ul><li><p><strong>广域网（WAN）</strong></p><p>广域网的任务是提供长距离通信，运送主机所发送的数据，其覆盖范围通常是直径为几十米到几千千米的区域。广域网是互联网的核心部分。连接广域网的各节点交换机的链路一般都是高速链路，具有较大的通信容量。</p></li><li><p><strong>城域网（MAN）</strong></p><p>城域网的覆盖范围可以跨越几个街区甚至整个城市，覆盖区域的直径为 5 ~ 50km 。城域网大多采用以太网技术，因此有时也常并入局域网的范围讨论。</p></li><li><p><strong>局域网（LAN）</strong></p><p>局域网一般用主机通过高速线路相连，覆盖范围较小，通常是直径为几十到几千米的区域。传统上，局域网使用广播技术，而广域网使用交换技术。</p></li><li><p><strong>个人区域网（PAN）</strong></p><p>个人区域网是指在个人工作的地方将消费电子设备（如平板电脑、智能手机等）用无线技术连接起来的网络，也称无线个人区域网（WPAN）。</p></li></ul><h2 id="按传输技术分类" tabindex="-1">按传输技术分类 <a class="header-anchor" href="#按传输技术分类" aria-label="Permalink to &quot;按传输技术分类&quot;">​</a></h2><ul><li><p><strong>广播式网络</strong></p><p>所有联网计算机都共享一个公共通信信道。当一台计算机利用共享通信信道发送报文分组时，所有其他计算机都会＂收听＂到这个分组。＂收听＂到该分组的计算机将通过检查目的地址来决定是否接收该分组。局域网基本上都采用广播式通信技术，广域网中的无线、卫星通信网络也采用广播式通信技术。</p></li><li><p><strong>点对点网络</strong></p><p>每条物理线路连接一对计算机。若通信的两台主机之间没有直接连接的线路，则它们之间的分组传输就要通过中间节点进行存储和转发，直至目的主机。</p></li></ul><h2 id="按拓扑结构分类" tabindex="-1">按拓扑结构分类 <a class="header-anchor" href="#按拓扑结构分类" aria-label="Permalink to &quot;按拓扑结构分类&quot;">​</a></h2><p>网络拓扑结构是指由网中节点（路由器、主机等）与通信线路之间的几何关系表示的网络结构，主要指通信子网的拓扑结构。按拓扑结构，网络可分为总线形、星形、环形和网状网络等，如图所示。星形、总线形和环形网络多用于局域网，网状网络多用于广域网。</p><br><div style="display:flex;flex-direction:column;align-items:center;"><img src="'+l+'" alt="HTML 初体验" width="650px" style="border-radius:10px;"></div><br><ul><li><p><strong>总线形网络</strong></p><p>用单根传输线把计算机连接起来。优点是建网容易、增／减节点方便、节省线路。缺点是重负载时通信效率不高、总线任意一处对故障敏感。</p></li><li><p><strong>星形网络</strong></p><p>每个终端或计算机都以单独的线路与中央设备相连。中央设备一般是交换机或路由器。优点是便于集中控制和管理。缺点是成本高、中央设备对故障敏感。</p></li><li><p><strong>环形网络</strong></p><p>所有计算机接口设备连接成一个环。环形网络最典型的例子是令牌环局域网。环既可以是单环，又可以是双环，环中信号是单向传输的。</p></li><li><p><strong>网状网络</strong></p><p>一般情况下，每个节点至少有两条路径与其他节点相连，多用在广域网中。其有规则型和非规则型两种。优点是可靠性高。缺点是控制复杂、线路成本高。</p></li></ul><p>以上 4 种基本的网络拓扑结构可以互连为更复杂的网络。</p><h2 id="按使用者分类" tabindex="-1">按使用者分类 <a class="header-anchor" href="#按使用者分类" aria-label="Permalink to &quot;按使用者分类&quot;">​</a></h2><ul><li><p><strong>公用网（Public Network）</strong></p><p>指电信公司出资建造的大型网络。“公用”的意思是指所有愿意按电信公司的规定缴纳费用的人都可使用这种网络。</p></li><li><p><strong>专用网（Private Network）</strong></p><p>指某个单位为满足本单位特殊业务的需要而建造的网络。这种网络不向本单位外的人提供服务，如铁路、电力、军队等部门的专用网。</p></li></ul><h2 id="按传输介质分类" tabindex="-1">按传输介质分类 <a class="header-anchor" href="#按传输介质分类" aria-label="Permalink to &quot;按传输介质分类&quot;">​</a></h2><p>传输介质可分为有线和无线两大类，因此网络可分为<strong>有线网络</strong>和<strong>无线网络</strong>。</p><p>有线网络可分为双绞线网络、同轴电缆网络等，而无线网络又可分为蓝牙、微波、无线电等类型。</p>',17)]))}const h=a(p,[["render",i]]);export{c as __pageData,h as default};
